package nodeleafbinding

import (
	"compress/gzip"
	"context"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"io"
	"reflect"
	"strconv"
	"strings"
	"talenro.local/platform/internal/nodecontrol/nodecerttime"
	"testing"
)

type leafBindingManifest struct {
	Input      string
	Raw        map[string]string
	Lower      string
	Error      string
	Projection Projection
}
type leafBindingOriginalEntry struct {
	Input                                          string
	Raw                                            map[string]string
	Certificate, Time, CertificateError, TimeError string
}

func leafBindingDecode(t testing.TB, text string, into any) {
	t.Helper()
	b, e := base64.StdEncoding.DecodeString(text)
	if e != nil {
		t.Fatal(e)
	}
	z, e := gzip.NewReader(strings.NewReader(string(b)))
	if e != nil {
		t.Fatal(e)
	}
	defer z.Close()
	b, e = io.ReadAll(z)
	if e != nil {
		t.Fatal(e)
	}
	if e = json.Unmarshal(b, into); e != nil {
		t.Fatal(e)
	}
}
func leafBindingFixture(t testing.TB, name string) Input {
	t.Helper()
	var packets map[string]Input
	leafBindingDecode(t, leafBindingFrozenInputs, &packets)
	in, ok := packets[name]
	if !ok {
		t.Fatal("unknown frozen fixture", name)
	}
	return in
}
func leafBindingHash(b []byte) string { d := sha256.Sum256(b); return hex.EncodeToString(d[:]) }
func leafBindingJSONHash(t testing.TB, in any) string {
	t.Helper()
	b, e := json.Marshal(in)
	if e != nil {
		t.Fatal(e)
	}
	return leafBindingHash(b)
}
func leafBindingRawHashes(v reflect.Value, path string, out map[string]string) {
	switch v.Kind() {
	case reflect.Pointer:
		if !v.IsNil() {
			leafBindingRawHashes(v.Elem(), path, out)
		}
	case reflect.Struct:
		for i := 0; i < v.NumField(); i++ {
			leafBindingRawHashes(v.Field(i), path+"."+v.Type().Field(i).Name, out)
		}
	case reflect.Slice:
		if v.Type().Elem().Kind() == reflect.Uint8 {
			out[path] = leafBindingHash(v.Bytes())
			return
		}
		for i := 0; i < v.Len(); i++ {
			leafBindingRawHashes(v.Index(i), path+"["+strconv.Itoa(i)+"]", out)
		}
	}
}
func assertLeafBindingLower(t testing.TB, in Input) nodecerttime.Summary {
	t.Helper()
	m, e := nodecerttime.Evaluate(context.Background(), in)
	if m != nil {
		defer m.Clear()
	}
	if e != nil || m == nil {
		t.Fatal("full lower positive control", e)
	}
	s := m.Summary()
	if s.Proof != nodecerttime.NodeCertificateConditionalTimeBound {
		t.Fatal("lower proof")
	}
	return s
}
func leafBindingExpected(t testing.TB, name string) leafBindingManifest {
	t.Helper()
	var entries map[string]leafBindingManifest
	leafBindingDecode(t, leafBindingFrozenManifest, &entries)
	m, ok := entries[name]
	if !ok {
		t.Fatal("unknown frozen manifest", name)
	}
	return m
}
func TestLeafBindingFixtureControls(t *testing.T) {
	var original, packets map[string]Input
	var old map[string]leafBindingOriginalEntry
	var entries map[string]leafBindingManifest
	leafBindingDecode(t, leafBindingOriginalInputs, &original)
	leafBindingDecode(t, leafBindingOriginalManifest, &old)
	leafBindingDecode(t, leafBindingFrozenInputs, &packets)
	leafBindingDecode(t, leafBindingFrozenManifest, &entries)
	if len(original) != 34 || len(old) != 34 || len(packets) != 34 || len(entries) != 34 {
		t.Fatal("frozen inventory")
	}
	for name, in := range packets {
		t.Run(name, func(t *testing.T) {
			m, ok := entries[name]
			if !ok || leafBindingJSONHash(t, in) != m.Input || leafBindingJSONHash(t, original[name]) != old[name].Input {
				t.Fatal("input hash")
			}
			raw := map[string]string{}
			leafBindingRawHashes(reflect.ValueOf(in), "Input", raw)
			if !reflect.DeepEqual(raw, m.Raw) {
				t.Fatal("new raw hash")
			}
			originalRaw := map[string]string{}
			leafBindingRawHashes(reflect.ValueOf(original[name]), "Input", originalRaw)
			if !reflect.DeepEqual(raw, originalRaw) {
				t.Fatal("raw changed")
			}
			for path, h := range originalRaw {
				if old[name].Raw[path] != h {
					t.Fatal("original raw hash", path)
				}
			}
			lower, e := nodecerttime.Evaluate(context.Background(), in)
			if lower != nil {
				defer lower.Clear()
			}
			if m.Error != "" {
				if e == nil || e.Error() != m.Error || lower != nil {
					t.Fatal("negative control", e)
				}
			} else {
				if e != nil || lower == nil || leafBindingJSONHash(t, lower.Summary()) != m.Lower {
					t.Fatal("lower summary manifest", e)
				}
			}
		})
	}
}

const leafBindingOriginalInputs = ""
const leafBindingOriginalManifest = ""
const leafBindingFrozenInputs = ""
const leafBindingFrozenManifest = ""
